[4341]={["aftermath"]="Kharan asked for the chance to explain what had happened.",["atomIDs"]={"4341:description:1-52","4341:description:54-120","4341:description:122-178","4341:description:183-198","4341:description:203-225","4341:description:230-276","4341:description:278-375","4341:description:377-410","4341:description:415-463","4341:description:465-473","4341:description:475-489","4341:objective:1-55","4341:objective:60-166"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"4341:completion:1-23"},["minimumStage"]=2,["objectiveSummary"]="Find Kharan Mighthammer in Blackrock Depths for King Magni.",["opening"]="Magni's searchers had found no certain answer about his daughter's fate. Kharan, the guard meant to protect her, was reportedly imprisoned in Blackrock Depths; the king wanted him found before accepting that Moira might be dead.",["pending"]="{actor} would seek Kharan in Blackrock's prison.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} found Kharan Mighthammer.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="e54bd9e1f2b6975920d8a97bc84a44391fb519de4120846d67f8d91e7b3342b1",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[4342]={["aftermath"]="Kharan maintained that there had been nothing he could do.",["atomIDs"]={"4342:description:1-45","4342:objective:1-45"},["coverageQualification"]="PARTIAL_CONVERSATION_FRAME_MISSING_GOSSIP_BODY",["endingAtomIDs"]={"4342:completion:1-52"},["minimumStage"]=2,["objectiveSummary"]="Hear Kharan Mighthammer before judging him.",["opening"]="Kharan pleaded for the chance to explain himself before judgment was passed. Listening was necessary before any answer could be carried back about his conduct.",["pending"]="{actor} would hear Kharan's explanation.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} listened to Kharan's account.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="682907474c27184bc36c24a336f75937cd7f8cdf898b16d4e60e762c0449cefb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability","gossipDialogueBody"}},
[4361]={["aftermath"]="Magni answered the report by striking his fist down in anger.",["atomIDs"]={"4361:description:1-54","4361:description:56-79","4361:objective:1-71"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"4361:completion:1-42"},["minimumStage"]=2,["objectiveSummary"]="Return the report to King Magni in Ironforge.",["opening"]="The news had to reach Magni before any response could be decided. The king, rather than a distant messenger, was to judge what should happen next.",["pending"]="{actor} would carry the news to King Magni.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the report to Magni.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="d3fee9c3c29d12befc46810373a48dd7d29e049a5c06677a1f0b9a119d2523d7",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[4362]={["aftermath"]="Moira wept over Thaurissan's death rather than celebrating the promised rescue.",["atomIDs"]={"4362:description:1-106","4362:description:111-138","4362:description:140-179","4362:description:184-282","4362:description:287-310","4362:description:312-359","4362:description:361-429","4362:objective:1-117"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"4362:completion:1-72","4362:completion:77-82"},["minimumStage"]=2,["objectiveSummary"]="Defeat Thaurissan and rescue Moira without harming her.",["opening"]="Magni believed his old adversary had enchanted Moira and held Ironforge at his mercy. The rescue order demanded Thaurissan's death while insisting that anything Moira did or said must not provoke an attack on her.",["pending"]="{actor} would return to the Depths to confront the emperor and spare Moira.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} defeated Thaurissan while leaving Moira alive.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="b13a72c1dfed8c6fd3440e9f0bff1ca5a8c8868aa2f89f357185979dbc5eb9bb",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[4363]={["aftermath"]="Magni regarded the news as Thaurissan's victory even in death and dismissed the messenger while he considered the changed future.",["atomIDs"]={"4363:description:1-43","4363:description:45-95","4363:description:100-208","4363:description:213-319","4363:description:324-363","4363:objective:1-58"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"4363:completion:1-42","4363:completion:47-94","4363:completion:99-120","4363:completion:122-187","4363:completion:192-276"},["minimumStage"]=2,["objectiveSummary"]="Take Moira's message about her unborn heir to Magni.",["opening"]="Moira defended Thaurissan as honorable and condemned his death. She ordered the news of her unborn Dark Iron child carried to Ironforge, declaring that the child's place in the succession did not depend on Magni's approval.",["pending"]="{actor} would carry Moira's message to her father.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} told Magni of the unborn Dark Iron heir.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="d7b6ba42dc2c20e9553b99bf06822fad491603cc561ed6f4e0eef78616a5fc69",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
