[4441]={["aftermath"]="Eridan prepared to attempt the repair while still hoping its damage could be undone.",["atomIDs"]={"4441:description:1-123","4441:description:128-257","4441:description:259-362","4441:description:364-405","4441:description:410-445","4441:description:447-510","4441:objective:1-105","4441:objective:107-144"},["endingAtomIDs"]={"4441:completion:1-14","4441:completion:16-82"},["opening"]="Eridan traced the flute to wood taken from an ancient protector. Fel magic had left its spirit bound and tortured, and blessed water offered a possible means of purification.",["pending"]="{actor} intended to fill the vial at the Temple of the Moon.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the blessed water.",["sourceHash"]="0a54310ca04b750a2d4f38df86520e2a39ae9ff9f848ff204f508b8ae474fc2c",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
