[4542]={["aftermath"]="Longhorn reported that raiders had destroyed a supply caravan and its entire party.",["atomIDs"]={"4542:description:1-71","4542:description:73-138","4542:description:140-233","4542:description:238-282","4542:description:284-330","4542:objective:1-67"},["endingAtomIDs"]={"4542:completion:1-14","4542:completion:16-48","4542:completion:50-119","4542:completion:121-170"},["opening"]="Renewed centaur attacks demanded a message to Freewind Post. Moonhorn also warned that nearby Grimtotem had begun acting strangely toward his people.",["pending"]="{actor} planned to carry the urgent message to Longhorn.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered Moonhorn's message.",["sourceHash"]="48d2232afe58ed6ba895c13cfd062c1c62bb42928477cf54957d1da9600e9374",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
