[4642]={["aftermath"]="Fuely resolved to study the environmental questions further after hearing the result.",["atomIDs"]={"4642:description:1-73","4642:description:75-129","4642:description:131-164","4642:description:166-271","4642:description:276-350","4642:description:352-393","4642:objective:1-57"},["endingAtomIDs"]={"4642:completion:1-23","4642:completion:25-47","4642:completion:52-63","4642:completion:65-143","4642:completion:145-249","4642:completion:254-289","4642:completion:291-323","4642:completion:325-352"},["opening"]="Fuely supplied encased Felwood ooze for release beside a pure crater specimen. A sample of the interaction's remainder would let him examine how contrasting environments had changed the creatures.",["pending"]="{actor} meant to perform the ooze experiment and recover a sample.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the merged specimen.",["sourceHash"]="479a124b06233fcef11d533e5dd694e74919e66a11d493b715b8dd365be0263a",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
