[4701]={["aftermath"]="Helendis described the beast as corrupted by dark magic and praised the blow against the orcs' supply.",["atomIDs"]={"4701:description:1-66","4701:description:71-145","4701:description:147-285","4701:description:287-360","4701:description:362-372","4701:description:374-385","4701:description:390-403","4701:description:405-431","4701:objective:1-68","4701:objective:70-118","4701:objective:120-171"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"4701:completion:1-36","4701:completion:38-85","4701:completion:87-155"},["minimumStage"]=2,["objectiveSummary"]="Find and destroy Halycon, the source of Blackrock's worgs.",["opening"]="Helendis's scouts traced the Blackrock orcs' seemingly endless worg supply to breeding and training inside the Spire. Removing its source, rather than repeatedly killing the exported animals, became the purpose of the hunt.",["pending"]="{actor} would seek Halycon within Blackrock Spire.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} defeated Halycon and reported to Helendis.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="d6aa7606359cda632d741c49496f32262d1f03175e3321d02c002ab5bc251ba9",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[4721]={["atomIDs"]={"4721:description:1-128","4721:description:130-201","4721:description:203-306","4721:description:311-384","4721:description:386-481","4721:objective:1-81"},["opening"]="Runners reported small southern caves surrounded by more wildkin. Trull suspected something valuable there and attributed the guardians' madness to whatever they protected.",["pending"]="{actor} meant to confront ten berserk owlbeasts.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} fulfilled the southern-cave assignment.",["sourceHash"]="20c03065f06c1e86586dc411f4e694f2273da8c74dce8af1fc8a310502128a91",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[4722]={["atomIDs"]={"4722:description:1-98","4722:description:101-196","4722:description:199-346","4722:objective:1-66"},["opening"]="Murlocs had scavenged a beached turtle and camped around its remains. Enough usable material survived to carry a sample to Gwennyth's investigation.",["pending"]="{actor} planned to take a sample of the Sea Turtle Remains to Gwennyth.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the recovered Sea Turtle Remains to Gwennyth.",["sourceHash"]="0f00868a0490598755828b3dc0e6f7b94710fd26fefda57f4cbc74230aec1174",["sourceRaceMask"]="77",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
